def longest_word(words):
    if not words:
        return None
    return max(words, key=len)

def rotate_items(items, k):
    if not items:
        return None
    if k < 0:
        raise ValueError("k must be nonnegative")
    k %= len(items)
    return tuple(items[-k:] + items[:-k]) if k else tuple(items)

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must be equally sized")
    if not left:
        return None
    return tuple(item for pair in zip(left, right) for item in pair)

def sort_labels(labels):
    unique = {}
    for label in labels:
        key = label.casefold()
        if key not in unique:
            unique[key] = label
    if not unique:
        return None
    return tuple(sorted(unique.values(), key=lambda label: label.casefold()))

def find_products(products, query):
    products = tuple(products)
    if not products:
        return None

    normalized_query = query.casefold()
    matches = [
        product
        for product in products
        if normalized_query in product["name"].casefold()
    ]
    return tuple(sorted(matches, key=lambda product: product["score"], reverse=True))

def group_words(words):
    if not words:
        return None

    groups = {}
    for word in words:
        key = word[0].casefold()
        groups.setdefault(key, []).append(word)

    return tuple((key, tuple(group)) for key, group in groups.items())

def parse_integer_fields(fields):
    if not fields:
        return None
    return tuple(int(field) for field in fields)

def nearest_date(dates, target):
    from datetime import date

    if not dates:
        return None

    target_date = date.fromisoformat(target)
    return min(
        dates,
        key=lambda value: abs(date.fromisoformat(value) - target_date),
    )

def median_value(values):
    ordered = sorted(values)
    n = len(ordered)
    if n == 0:
        return None
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2

def merge_ranges(ranges):
    if not ranges:
        return None

    sorted_ranges = sorted((range_[0], range_[1]) for range_ in ranges)
    merged = [sorted_ranges[0]]

    for start, end in sorted_ranges[1:]:
        previous_start, previous_end = merged[-1]
        if start <= previous_end:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))

    return tuple(merged)

def shortest_path(graph, start, goal):
    if start not in graph or goal not in graph:
        raise ValueError("start and goal must be nodes in the graph")

    if start == goal:
        return (start,)

    from collections import deque

    queue = deque([(start, (start,))])
    visited = {start}

    while queue:
        node, path = queue.popleft()

        for neighbor in graph[node]:
            if neighbor in visited:
                continue

            next_path = path + (neighbor,)
            if neighbor == goal:
                return next_path

            visited.add(neighbor)
            queue.append((neighbor, next_path))

    return None

def topological_order(nodes, edges):
    import heapq

    ordered_nodes = list(dict.fromkeys(nodes))
    if not ordered_nodes:
        return None

    position = {node: index for index, node in enumerate(ordered_nodes)}
    adjacency = {node: [] for node in ordered_nodes}
    indegree = {node: 0 for node in ordered_nodes}

    for source, destination in edges:
        adjacency[source].append(destination)
        indegree[destination] += 1

    ready = [
        (position[node], node)
        for node in ordered_nodes
        if indegree[node] == 0
    ]
    heapq.heapify(ready)

    result = []
    while ready:
        _, node = heapq.heappop(ready)
        result.append(node)
        for destination in adjacency[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heapq.heappush(ready, (position[destination], destination))

    return tuple(result)
